          status,
          archivedInSect: archiveIds.includes(f.id),
          knownAccounts: visibleAccounts,
          evidenceLineageCount: wf && Array.isArray(wf.evidenceLineages) ? wf.evidenceLineages.length : 0,
          storyId: f.storyId || null
