        polityId: s.polityId,
        anchorNodeIds: veiled ? [] : s.anchorNodeIds.slice(),
        locationNode: veiled ? null : locNode,
        summaryTh: veiled ? 'ยังไม่มีศิษย์หรือสายข่าวในสำนักไปพบเบาะแสของเรื่องราวนี้' : s.summaryTh,
        status: st.status || 'dormant',
